/* babel-plugin-inline-import './constants/shaders/fuseI.frag' */
const fuseShaderSrcI = "precision highp float;\nprecision highp int;\nprecision highp sampler2D;\nprecision highp sampler3D;\n\n// the lut texture is a 256x1 rgba texture for each channel\nuniform sampler2D lutSampler;\n\nuniform vec2 lutMinMax;\n\n// src texture is the raw volume intensity data\nuniform isampler2D srcTexture;\n\nvoid main() {\n    ivec2 vUv = ivec2(int(gl_FragCoord.x), int(gl_FragCoord.y));\n    int intensity = texelFetch(srcTexture, vUv, 0).r;\n    float ilookup = float(float(intensity) - lutMinMax.x) / float(lutMinMax.y - lutMinMax.x);\n    // apply lut to intensity:\n    vec4 pix = texture(lutSampler, vec2(ilookup, 0.5));\n    gl_FragColor = vec4(pix.xyz * pix.w, pix.w);\n}\n";
/* babel-plugin-inline-import './constants/shaders/colorizeUI.frag' */
const colorizeSrcUI = "precision highp float;\nprecision highp int;\nprecision highp usampler2D;\nprecision highp sampler3D;\n\nuniform sampler2D featureData;\n/** Min and max feature values that define the endpoints of the color map. Values\n * outside the range will be clamped to the nearest endpoint.\n */\nuniform float featureColorRampMin;\nuniform float featureColorRampMax;\nuniform sampler2D colorRamp;\nuniform usampler2D inRangeIds;\nuniform usampler2D outlierData;\n\n// TODO: Rename to 'localId' for consistency\n/**\n * LUT mapping from the segmentation ID (raw pixel value) to the\n * global ID (index in data buffers like 'featureData' and 'outlierData').\n * \n * For a given segmentation ID 'segId', the global ID is given by:\n * 'segIdToGlobalId[segId - segIdOffset] - 1'.\n*/\nuniform usampler2D segIdToGlobalId;\nuniform uint segIdOffset;\n\nuniform vec3 outlineColor;\n\n/** MUST be synchronized with the DrawMode enum in ColorizeCanvas! */\nconst uint DRAW_MODE_HIDE = 0u;\nconst uint DRAW_MODE_COLOR = 1u;\nconst uint BACKGROUND_ID = 0u;\nconst uint MISSING_DATA_ID = 0xFFFFFFFFu;\n\nuniform vec3 outlierColor;\nuniform uint outlierDrawMode;\nuniform vec3 outOfRangeColor;\nuniform uint outOfRangeDrawMode;\n\nuniform uint highlightedId;\n\nuniform bool useRepeatingCategoricalColors;\n\n// src texture is the raw volume intensity data\nuniform usampler2D srcTexture;\n\nvec4 getFloatFromTex(sampler2D tex, int index) {\n  int width = textureSize(tex, 0).x;\n  ivec2 featurePos = ivec2(index % width, index / width);\n  return texelFetch(tex, featurePos, 0);\n}\nuvec4 getUintFromTex(usampler2D tex, int index) {\n  int width = textureSize(tex, 0).x;\n  ivec2 featurePos = ivec2(index % width, index / width);\n  return texelFetch(tex, featurePos, 0);\n}\nuint getId(ivec2 uv) {\n  uint rawId = texelFetch(srcTexture, uv, 0).r;\n  if (rawId == 0u) {\n    return BACKGROUND_ID;\n  }\n  uvec4 c = getUintFromTex(segIdToGlobalId, int(rawId - segIdOffset));\n  // Note: IDs are offset by '1' to reserve '0' for segmentations that don't\n  // have associated data. '1' MUST be subtracted from the ID when accessing\n  // data buffers.\n  uint globalId = c.r;\n  if (globalId == 0u) {\n    return MISSING_DATA_ID;\n  }\n  return globalId;\n}\n\nvec4 getColorRamp(float val) {\n  float width = float(textureSize(colorRamp, 0).x);\n  float range = (width - 1.0) / width;\n  float adjustedVal = (0.5 / width) + (val * range);\n  return texture(colorRamp, vec2(adjustedVal, 0.5));\n}\n\nvec4 getCategoricalColor(float featureValue) {\n  float width = float(textureSize(colorRamp, 0).x);\n  float modValue = mod(featureValue, width);\n  // The categorical texture uses no interpolation, so when sampling, 'modValue'\n  // is rounded to the nearest integer.\n  return getColorRamp(modValue / (width - 1.0));\n}\n\nvec4 getColorFromDrawMode(uint drawMode, vec3 defaultColor) {\n  const uint DRAW_MODE_HIDE = 0u;\n  vec3 backgroundColor = vec3(0.0, 0.0, 0.0);\n  if (drawMode == DRAW_MODE_HIDE) {\n    return vec4(backgroundColor, 0.0);\n  } else {\n    return vec4(defaultColor, 1.0);\n  }\n}\n\nfloat getFeatureVal(uint id) {\n  // Data buffer starts at 0, non-background segmentation IDs start at 1\n  return getFloatFromTex(featureData, int(id) - 1).r;\n}\nuint getOutlierVal(uint id) {\n  // Data buffer starts at 0, non-background segmentation IDs start at 1\n  return getUintFromTex(outlierData, int(id) - 1).r;\n}\nbool getIsInRange(uint id) {\n  return getUintFromTex(inRangeIds, int(id) - 1).r == 1u;\n}\nbool getIsOutlier(float featureVal, uint outlierVal) {\n  return isinf(featureVal) || outlierVal != 0u;\n}\n\nvec4 getObjectColor(ivec2 sUv, float opacity) {\n  // Get the segmentation id at this pixel\n  uint id = getId(sUv);\n\n  // A segmentation id of 0 represents background\n  if (id == BACKGROUND_ID) {\n    return vec4(0, 0, 0, 0);\n  }\n\n  // color the highlighted object. Note, 'highlightedId' is a 0-based index\n  // (global ID w/o offset), while 'id' is a 1-based index.\n  // if (id - 1u == highlightedId) {\n  //   return vec4(outlineColor, 1.0);\n  // }\n\n  float featureVal = getFeatureVal(id);\n  uint outlierVal = getOutlierVal(id);\n  float normFeatureVal = (featureVal - featureColorRampMin) / (featureColorRampMax - featureColorRampMin);\n\n  // Use the selected draw mode to handle out of range and outlier values;\n  // otherwise color with the color ramp as usual.\n  bool isInRange = getIsInRange(id);\n  bool isOutlier = getIsOutlier(featureVal, outlierVal);\n  bool isMissingData = (id == MISSING_DATA_ID);\n\n  // Features outside the filtered/thresholded range will all be treated the same (use 'outOfRangeDrawColor').\n  // Features inside the range can either be outliers or standard values, and are colored accordingly.\n  vec4 color;\n  if (isMissingData) { \n    // TODO: Add color controls for missing data\n    color = getColorFromDrawMode(outlierDrawMode, outlierColor);\n  } else if (isInRange) {\n    if (isOutlier) {\n      color = getColorFromDrawMode(outlierDrawMode, outlierColor);\n    } else if (useRepeatingCategoricalColors) {\n      color = getCategoricalColor(featureVal);\n    } else {\n      color = getColorRamp(normFeatureVal);\n    }\n  } else {\n    color = getColorFromDrawMode(outOfRangeDrawMode, outOfRangeColor);\n  }\n  color.a *= opacity;\n  return color;\n}\n\nvoid main() {\n  ivec2 vUv = ivec2(int(gl_FragCoord.x), int(gl_FragCoord.y));\n  gl_FragColor = getObjectColor(vUv, 1.0);\n}\n";
/**
 * Immutable snapshot of the Channel fields needed by gpuFuse, captured at fuse() time.
 * Snapshot is required to avoid race conditions because Channels are mutable.
 */
// This is the owner of the fused RGBA volume texture atlas, and the mask texture atlas.
// This module is responsible for updating the fused texture, given the read-only volume channel data.
export default class FusedChannelData {
  constructor(atlasX, atlasY) {
    // allow for resizing
    this.width = atlasX;
    this.height = atlasY;
    this.maskTexture = new DataTexture(new Uint8ClampedArray(this.width * this.height).fill(255), this.width, this.height, RedFormat, UnsignedByteType);
    this.maskTexture.generateMipmaps = false;
    this.maskTexture.magFilter = LinearFilter;
    this.maskTexture.minFilter = LinearFilter;
    this.maskTexture.wrapS = ClampToEdgeWrapping;
    this.maskTexture.wrapT = ClampToEdgeWrapping;
    // for single-channel tightly packed array data:
    this.maskTexture.unpackAlignment = 1;
    this.fuseRequested = null;
    this.fuseScene = new Scene();
    this.quadCamera = new OrthographicCamera(-1, 1, 1, -1, 0, 1);
    this.fuseRenderTarget = new WebGLRenderTarget(this.width, this.height, {
      minFilter: LinearFilter,
      magFilter: LinearFilter,
      format: RGBAFormat,
      type: UnsignedByteType,
      // FloatType ?
      depthBuffer: false,
      stencilBuffer: false,
      generateMipmaps: false,
      wrapS: ClampToEdgeWrapping,
      wrapT: ClampToEdgeWrapping
    });
    this.fuseMaterialProps = {
      vertexShader: renderToBufferVertShader,
      depthTest: false,
      depthWrite: false,
      blending: CustomBlending,
      blendSrc: OneFactor,
      blendDst: OneFactor,
      blendEquation: MaxEquation
    };
    // this exists to keep one reference alive
    // to make sure we do not fully delete and re-create
    // a shader every time.
    this.fuseMaterialF = this.setupFuseMaterial(fuseShaderSrcF);
    this.fuseMaterialUI = this.setupFuseMaterial(fuseShaderSrcUI);
    this.fuseMaterialI = this.setupFuseMaterial(fuseShaderSrcI);
    this.fuseMaterialColorizeUI = this.setupFuseColorizeMaterial(colorizeSrcUI);
    this.fuseMaterialF.needsUpdate = true;
    this.fuseMaterialUI.needsUpdate = true;
    this.fuseMaterialI.needsUpdate = true;
    this.fuseGeometry = new PlaneGeometry(2, 2);
  }
  setupFuseMaterial(fragShaderSrc) {
    return new ShaderMaterial({
      uniforms: {
        highlightedId: {
          value: -1
        },
        lutSampler: {
          value: null
        },
        lutMinMax: {
          value: new Vector2(0, 255)
        },
        srcTexture: {
          value: null
        }
      },
      fragmentShader: fragShaderSrc,
      ...this.fuseMaterialProps
    });
  }
  setupFuseColorizeMaterial(fragShaderSrc) {
    // Float red texture R32F
    const initialFeatureData = new DataTexture(new Float32Array([0]), 1, 1, RedFormat, FloatType);
    initialFeatureData.needsUpdate = true;
    // Integer red texture (R8UI)
    const initialOutlierData = new DataTexture(new Uint8Array([0]), 1, 1, RedIntegerFormat, UnsignedByteType);
    initialOutlierData.needsUpdate = true;
    const initialInRangeIds = new DataTexture(new Uint32Array([0]), 1, 1, RedIntegerFormat, UnsignedByteType);
    initialInRangeIds.needsUpdate = true;
    // Integer red texture (R32UI)
    const initialSegIdToGlobalId = new DataTexture(new Uint32Array([0]), 1, 1, RedIntegerFormat, UnsignedIntType);
    initialSegIdToGlobalId.needsUpdate = true;
    // Float RGBA color ramp texture
    const initialColorRamp = new DataTexture(new Uint8Array([0, 0, 0, 1]), 1, 1, RGBAFormat, FloatType);
    initialColorRamp.needsUpdate = true;
    // 8-bit RGBA source texture
    const initialSrcTexture = new DataTexture(new Uint8Array([0, 0, 0, 255]), 1, 1, RGBAFormat, UnsignedByteType);
    initialSrcTexture.needsUpdate = true;
    return new ShaderMaterial({
      uniforms: {
        highlightedId: {
          value: -1
        },
        featureData: {
          value: initialFeatureData
        },
        outlierData: {
          value: initialOutlierData
        },
        inRangeIds: {
          value: initialInRangeIds
        },
        srcTexture: {
          value: initialSrcTexture
        },
        featureColorRampMin: {
          value: 0
        },
        featureColorRampMax: {
          value: 1
        },
        colorRamp: {
          value: initialColorRamp
        },
        useRepeatingCategoricalColors: {
          value: false
        },
        outlineColor: {
          value: new Color(0xffffff)
        },
        outlierColor: {
          value: new Color(0x444444)
        },
        outOfRangeColor: {
          value: new Color(0x444444)
        },
        outlierDrawMode: {
          value: 0
        },
        outOfRangeDrawMode: {
          value: 0
        },
        hideOutOfRange: {
          value: false
        },
        segIdToGlobalId: {
          value: initialSegIdToGlobalId
        },
        segIdOffset: {
          value: 0
        }
      },
      fragmentShader: fragShaderSrc,
      ...this.fuseMaterialProps
    });
  }
  getFusedTexture() {
    return this.fuseRenderTarget.texture;
  }
  cleanup() {
    this.fuseScene.clear();
    this.maskTexture.dispose();
  }
  getShader(dtype, isColorize) {
    switch (dtype) {
      case "float32":
        return this.fuseMaterialF;
      case "uint8":
      case "uint16":
      case "uint32":
        return isColorize ? this.fuseMaterialColorizeUI : this.fuseMaterialUI;
      case "int8":
      case "int16":
      case "int32":
        return this.fuseMaterialI;
      default:
        throw new Error("Unsupported data type for fuse shader");
    }
  }
  fuse(combination, channels) {
    /**
     * Snapshot channel state now so gpuFuse() is immune to concurrent loads
     * mutating the live Channel objects between fuse() and the next
     * requestAnimationFrame
     */
    const readyToFuse = [];
    for (let i = 0; i < combination.length; ++i) {
      const c = combination[i];
      const idx = c.chIndex;
      if (channels[idx].loaded) {
        // set the lut in this fuse combination.
        // can optimize by calling combineLuts more lazily
        c.lut = channels[idx].combineLuts(c.rgbColor, c.lut);
        if (c.rgbColor) {
          readyToFuse.push({
            ...c,
            snapshot: {
              dtype: channels[idx].dtype,
              dataTexture: channels[idx].dataTexture,
              lutTexture: channels[idx].lutTexture,
              rawMin: channels[idx].rawMin,
              rawMax: channels[idx].rawMax,
              frame: channels[idx].frame
            }
          });
        }
      }
    }
    if (readyToFuse.length === 0) {
      this.fuseRequested = null;
      return;
    }
    this.fuseRequested = readyToFuse;
  }
  gpuFuse(renderer) {
    const combination = this.fuseRequested;
    if (!combination) {
      return;
    }

    // webgl draw one mesh per channel to fuse.  clear texture to 0,0,0,0

    this.fuseScene.traverse(node => {
      if (node instanceof Mesh) {
        // materials were holding references to the channel data textures
        // causing mem leak so we must dispose before clearing the scene
        node.material.dispose();
      }
    });
    this.fuseScene.clear();
    for (let i = 0; i < combination.length; ++i) {
      const chIndex = combination[i].chIndex;
      const snap = combination[i].snapshot;
      const isColorize = combination[i].feature !== undefined;
      // add a draw call per channel here.
      // must clone the material to keep a unique set of uniforms
      const mat = this.getShader(snap.dtype, isColorize).clone();
      mat.uniforms.srcTexture.value = snap.dataTexture;
      const feature = combination[i].feature;
      if (isColorize && feature) {
        mat.uniforms.featureData.value = feature.idsToFeatureValue;
        mat.uniforms.outlierData.value = feature.outlierData;
        mat.uniforms.inRangeIds.value = feature.inRangeIds;
        mat.uniforms.featureColorRampMin.value = feature.featureMin;
        mat.uniforms.featureColorRampMax.value = feature.featureMax;
        mat.uniforms.colorRamp.value = feature.featureValueToColor;
        mat.uniforms.useRepeatingCategoricalColors.value = feature.useRepeatingColor;
        mat.uniforms.outlineColor.value = feature.outlineColor;
        mat.uniforms.outlierColor.value = feature.outlierColor;
        mat.uniforms.outOfRangeColor.value = feature.outOfRangeColor;
        mat.uniforms.outlierDrawMode.value = feature.outlierDrawMode;
        mat.uniforms.outOfRangeDrawMode.value = feature.outOfRangeDrawMode;
        mat.uniforms.hideOutOfRange.value = feature.hideOutOfRange;
        let globalIdLookupInfo = feature.frameToGlobalIdLookup.get(snap.frame);
        if (!globalIdLookupInfo) {
          console.warn(`FusedChannelData.gpuFuse: No global ID lookup info for frame ${snap.frame} in channel ${chIndex}. A default lookup will be used, which may cause visual artifacts.`);
          const texture = new DataTexture(new Uint32Array([0]), 1, 1, RedIntegerFormat, UnsignedIntType);
          texture.needsUpdate = true;
          globalIdLookupInfo = {
            texture,
            minSegId: 1
          };
        }
        mat.uniforms.segIdToGlobalId.value = globalIdLookupInfo.texture;
        mat.uniforms.segIdOffset.value = globalIdLookupInfo.minSegId;
      } else {
        // the lut texture is spanning only the data range of the channel, not the datatype range
        mat.uniforms.lutMinMax.value = new Vector2(snap.rawMin, snap.rawMax);
        mat.uniforms.lutSampler.value = snap.lutTexture;
      }
      this.fuseScene.add(new Mesh(this.fuseGeometry, mat));
    }
    if (this.fuseScene.children.length > 0) {
      renderer.setRenderTarget(this.fuseRenderTarget);
      renderer.autoClearColor = true;
      const prevClearColor = new Color();
      renderer.getClearColor(prevClearColor);
      const prevClearAlpha = renderer.getClearAlpha();
      renderer.setClearColor(0x000000, 0);
      renderer.render(this.fuseScene, this.quadCamera);
      renderer.setRenderTarget(null);
      renderer.setClearColor(prevClearColor, prevClearAlpha);
    }
    // "dirty flag"
    this.fuseRequested = null;
  }

  // currently only one channel can be selected to participate as a mask
  setChannelAsMask(idx, channel) {
    if (!channel || !channel.loaded) {
      return false;
    }
    // binarize the data
    // (TODO consider whether it should be binarized or not?)
    const datacopy = new Uint8ClampedArray(channel.imgData.data.length);
    for (let i = 0; i < channel.imgData.data.length; i++) {
      datacopy[i] = channel.imgData.data[i] > 0 ? 255 : 0;
    }
    const maskData = {
      data: datacopy,
      width: this.width,
      height: this.height,
      colorSpace: "srgb"
    };
    this.maskTexture.image = maskData;
    this.maskTexture.needsUpdate = true;
    return true;
  }
}